    { title: "玄幻奇幻", url: "/sort/1_{{page}}/", flexBasis: 0.25 },
    { title: "武侠仙侠", url: "/sort/2_{{page}}/", flexBasis: 0.25 },
    { title: "都市言情", url: "/sort/3_{{page}}/", flexBasis: 0.25 },
    { title: "历史穿越", url: "/sort/4_{{page}}/", flexBasis: 0.25 },

    { title: "网游竞技", url: "/sort/5_{{page}}/", flexBasis: 0.25 },
    { title: "科幻灵异", url: "/sort/6_{{page}}/", flexBasis: 0.25 },
    { title: "恐怖惊悚", url: "/sort/7_{{page}}/", flexBasis: 0.25 },
    { title: "其他类型", url: "/sort/8_{{page}}/", flexBasis: 0.25 }
];

var result = [];
for (var i = 0; i < menus.length; i++) {
    var item = menus[i];
    var style = {
        layout_flexGrow: 1,
        layout_flexBasisPercent: item.flexBasis
    };

    result.push({
        title: item.title,
        url: item.url,
        style: style
    });
}

JSON.stringify(result);

